sealed class Result<T> {}

class Success<T> extends Result<T> {
  Success(this.data);
  final T data;
}

class Failure<T> extends Result<T> {
  Failure(this.message);
  final String message;
}

String render(Result<int> r) => switch (r) {
      Success(:final data) => 'data $data',
      Failure(:final message) => 'error $message',
    };

void main() {
  print(render(Success(3)));
  print(render(Failure('timeout')));
}

abstract interface class UserRepository {
  Future<String> fetchName();
}

class ApiUserRepository implements UserRepository {
  int calls = 0;

  @override
  Future<String> fetchName() async {
    calls++;
    return 'An';
  }
}

class CachedUserRepository implements UserRepository {
  CachedUserRepository(this._inner);
  final UserRepository _inner;
  String? _cache;

  @override
  Future<String> fetchName() async => _cache ??= await _inner.fetchName();
}

Future<void> main() async {
  final api = ApiUserRepository();
  final repo = CachedUserRepository(api);
  print(await repo.fetchName());
  print(await repo.fetchName());
  print(api.calls);
}
